'use client';

import { useId, useRef, useState, type DragEvent } from 'react';
import './file-dropzone.css';

export type FileDropzoneProps = {
  label?: string;
  accept?: string;
  fileTypesLabel?: string;
  multiple?: boolean;
  maxFiles?: number;
  maxSize?: number;
  disabled?: boolean;
  onFilesChange?: (files: File[]) => void;
  className?: string;
};

const DEFAULT_MAX_SIZE = 10 * 1024 * 1024;

function formatBytes(bytes: number) {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(bytes < 10 * 1024 ? 1 : 0)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(bytes < 10 * 1024 * 1024 ? 1 : 0)} MB`;
}

function fileKey(file: File) {
  return JSON.stringify([file.name, file.size, file.lastModified, file.type]);
}

function matchesAccept(file: File, accept: string) {
  const rules = accept.split(',').map(rule => rule.trim().toLowerCase()).filter(Boolean);
  if (rules.length === 0) return true;
  const name = file.name.toLowerCase();
  const type = file.type.toLowerCase();
  return rules.some(rule => {
    if (rule.startsWith('.')) return name.endsWith(rule);
    if (rule === '*/*') return true;
    if (!type) return false;
    if (rule.endsWith('/*')) return type.startsWith(rule.slice(0, -1));
    return type === rule;
  });
}

/** Local file selection with validation. Connect onFilesChange to your own upload flow. */
export function FileDropzone({ label = 'Attachments', accept = '', fileTypesLabel, multiple = true, maxFiles = 5, maxSize = DEFAULT_MAX_SIZE, disabled = false, onFilesChange, className = '' }: FileDropzoneProps) {
  const uid = useId();
  const input = useRef<HTMLInputElement>(null);
  const browse = useRef<HTMLButtonElement>(null);
  const removeButtons = useRef(new Map<string, HTMLButtonElement>());
  const dragDepth = useRef(0);
  const selected = useRef<File[]>([]);
  const [files, setFiles] = useState<File[]>([]);
  const [errors, setErrors] = useState<string[]>([]);
  const [dragging, setDragging] = useState(false);
  const [announcement, setAnnouncement] = useState('');
  const countLimit = multiple ? (Number.isFinite(maxFiles) && maxFiles >= 1 ? Math.floor(maxFiles) : 5) : 1;
  const sizeLimit = Number.isFinite(maxSize) && maxSize >= 0 ? maxSize : DEFAULT_MAX_SIZE;
  const totalSize = files.reduce((total, file) => total + file.size, 0);
  const typesLabel = fileTypesLabel ?? (accept || 'Any file type');

  function commit(next: File[]) {
    selected.current = next;
    setFiles(next);
    onFilesChange?.([...next]);
  }

  function addFiles(incoming: File[]) {
    if (disabled || incoming.length === 0) return;
    const next = multiple ? [...selected.current] : [];
    const rejected: string[] = [];
    let added = 0;
    for (const file of incoming) {
      if (!matchesAccept(file, accept)) {
        rejected.push(`${file.name}: file type is not accepted.`);
      } else if (file.size > sizeLimit) {
        rejected.push(`${file.name}: exceeds ${formatBytes(sizeLimit)} per file.`);
      } else if (next.some(item => fileKey(item) === fileKey(file)) || (!multiple && added === 0 && selected.current.some(item => fileKey(item) === fileKey(file)))) {
        rejected.push(`${file.name}: already selected.`);
      } else if (next.length >= countLimit) {
        rejected.push(`${file.name}: maximum of ${countLimit} ${countLimit === 1 ? 'file' : 'files'} reached.`);
      } else {
        next.push(file);
        added += 1;
      }
    }
    if (added > 0) commit(next);
    setErrors(rejected);
    setAnnouncement([added > 0 ? `${added} ${added === 1 ? 'file' : 'files'} selected. ${next.length} total.` : 'No files added.', ...rejected].join(' '));
  }

  function removeFile(file: File) {
    if (disabled) return;
    const index = selected.current.findIndex(item => fileKey(item) === fileKey(file));
    const next = selected.current.filter(item => fileKey(item) !== fileKey(file));
    const adjacent = next[index] ?? next[index - 1];
    const focusTarget = adjacent ? removeButtons.current.get(fileKey(adjacent)) : browse.current;
    // Move focus to a surviving control before React removes the activated button.
    (focusTarget ?? browse.current)?.focus();
    commit(next);
    setErrors([]);
    setAnnouncement(`${file.name} removed. ${next.length} ${next.length === 1 ? 'file' : 'files'} selected.`);
  }

  function hasFiles(event: DragEvent<HTMLDivElement>) {
    return Array.from(event.dataTransfer.types).includes('Files');
  }

  return <section className={`ac-file-dropzone ${className}`.trim()} aria-labelledby={`${uid}-label`} aria-disabled={disabled} data-disabled={disabled}>
    <header className="ac-file-header"><h3 id={`${uid}-label`}>{label}</h3><span className="ac-file-count" aria-label={`${files.length} of ${countLimit} files selected`}>{files.length}<span aria-hidden="true"> / {countLimit}</span></span></header>
    <div className="ac-file-drop-area" data-dragging={dragging && !disabled} aria-describedby={`${uid}-hint${errors.length ? ` ${uid}-errors` : ''}`}
      onDragEnter={event => { if (!hasFiles(event)) return; event.preventDefault(); dragDepth.current += 1; if (!disabled) setDragging(true); }}
      onDragOver={event => { if (!hasFiles(event)) return; event.preventDefault(); event.dataTransfer.dropEffect = disabled ? 'none' : 'copy'; }}
      onDragLeave={event => { if (!hasFiles(event)) return; event.preventDefault(); dragDepth.current = Math.max(0, dragDepth.current - 1); if (dragDepth.current === 0) setDragging(false); }}
      onDrop={event => { event.preventDefault(); dragDepth.current = 0; setDragging(false); addFiles(Array.from(event.dataTransfer.files)); }}>
      <div className="ac-file-drop-icon" aria-hidden="true"><svg viewBox="0 0 28 32" fill="none"><path d="M5 1.5h12L26.5 11v17a2.5 2.5 0 0 1-2.5 2.5H5A2.5 2.5 0 0 1 2.5 28V4A2.5 2.5 0 0 1 5 1.5Z"/><path d="M17 2v9h9M9 21h11m-5.5-5.5v11"/></svg><span>+</span></div>
      <p className="ac-file-drop-title">{dragging && !disabled ? 'Release to select' : 'Drop files here'}</p>
      <p className="ac-file-drop-or">or choose from your device</p>
      <button ref={browse} type="button" className="ac-file-browse" disabled={disabled} onClick={() => input.current?.click()}>Choose {multiple ? 'files' : 'a file'}<span aria-hidden="true">↗</span></button>
      <input ref={input} className="ac-file-native-input" id={`${uid}-input`} type="file" accept={accept || undefined} multiple={multiple} disabled={disabled} tabIndex={-1} aria-label={`Choose ${label.toLowerCase()}`} onChange={event => { addFiles(Array.from(event.currentTarget.files ?? [])); event.currentTarget.value = ''; }}/>
      <p className="ac-file-hint" id={`${uid}-hint`}>{typesLabel}<span>{formatBytes(sizeLimit)} per file · {countLimit} {countLimit === 1 ? 'file' : 'files'} maximum</span></p>
    </div>
    {errors.length > 0 && <ul className="ac-file-errors" id={`${uid}-errors`}>{errors.map((error, index) => <li key={`${index}-${error}`}>{error}</li>)}</ul>}
    {files.length > 0 && <ul className="ac-file-list" aria-label="Selected files">{files.map(file => <li key={fileKey(file)}><span className="ac-file-type" aria-hidden="true">{file.name.includes('.') ? file.name.split('.').pop()?.slice(0, 4).toUpperCase() : 'FILE'}</span><span className="ac-file-meta"><strong title={file.name}>{file.name}</strong><span>{formatBytes(file.size)}</span></span><span className="ac-file-selected-mark" aria-hidden="true">✓</span><button ref={element => { if (element) removeButtons.current.set(fileKey(file), element); else removeButtons.current.delete(fileKey(file)); }} type="button" className="ac-file-remove" disabled={disabled} aria-label={`Remove ${file.name}`} onClick={() => removeFile(file)}><span aria-hidden="true">×</span></button></li>)}</ul>}
    <footer className="ac-file-footer"><span>{files.length ? `${files.length} ${files.length === 1 ? 'file' : 'files'} selected` : 'No files selected'}</span><span>{files.length ? formatBytes(totalSize) : `${countLimit} slots available`}</span></footer>
    <p className="ac-file-sr" aria-live="polite" aria-atomic="true">{announcement}</p>
  </section>;
}

.ac-file-dropzone { --ac-file-paper:#fffefa; --ac-file-ink:#242e27; --ac-file-muted:#6b726a; --ac-file-line:#d9ddd3; --ac-file-accent:#345a42; --ac-file-focus:#236eaa; box-sizing:border-box; container-type:inline-size; width:100%; max-width:640px; padding:24px; border:1px solid var(--ac-file-line); border-radius:16px; background:var(--ac-file-paper); color:var(--ac-file-ink); font-family:Arial,Helvetica,sans-serif; text-align:left; }
.ac-file-dropzone *, .ac-file-dropzone *::before, .ac-file-dropzone *::after { box-sizing:border-box; }
.ac-file-header { display:flex; align-items:center; justify-content:space-between; gap:16px; margin-bottom:18px; }.ac-file-header h3 { margin:0; font-size:17px; font-weight:600; letter-spacing:-.035em; }
.ac-file-count { flex-shrink:0; min-width:47px; padding:6px 9px; border:1px solid var(--ac-file-line); border-radius:6px; font-size:11px; font-variant-numeric:tabular-nums; text-align:center; }.ac-file-count > span { color:var(--ac-file-muted); }
.ac-file-drop-area { display:flex; align-items:center; flex-direction:column; padding:25px 18px 19px; border:1px dashed #b7c0b2; border-radius:10px; background:#f6f7f1; transition:background .15s,border-color .15s; }
.ac-file-drop-area[data-dragging=true] { border-color:var(--ac-file-accent); border-style:solid; background:#e7eedf; outline:3px solid #345a421c; outline-offset:3px; }
.ac-file-drop-icon { position:relative; display:grid; width:54px; height:54px; margin-bottom:15px; place-items:center; }.ac-file-drop-icon svg { width:31px; height:36px; stroke:#7d8b76; stroke-width:1.4; transform:rotate(-10deg); }.ac-file-drop-icon > span { position:absolute; right:0; bottom:0; display:grid; width:24px; height:24px; place-items:center; border:3px solid #f6f7f1; border-radius:50%; background:var(--ac-file-accent); color:white; font-size:16px; line-height:1; }.ac-file-drop-area[data-dragging=true] .ac-file-drop-icon > span { border-color:#e7eedf; }
.ac-file-drop-title { margin:0; font-size:19px; line-height:1.25; font-weight:500; letter-spacing:-.045em; }.ac-file-drop-or { margin:7px 0 17px; color:var(--ac-file-muted); font-size:12px; line-height:1.5; }
.ac-file-browse { display:flex; align-items:center; justify-content:space-between; gap:26px; min-height:40px; padding:10px 14px; border:1px solid var(--ac-file-accent); border-radius:6px; background:var(--ac-file-accent); color:#fff; font:500 12px/1.3 Arial,Helvetica,sans-serif; cursor:pointer; transition:background .15s; }.ac-file-browse > span { font-size:17px; line-height:1; }.ac-file-browse:hover:enabled { background:#244431; }.ac-file-browse:focus-visible,.ac-file-remove:focus-visible { outline:3px solid var(--ac-file-focus); outline-offset:4px; }
.ac-file-native-input { display:none; }.ac-file-hint { margin:18px 0 0; color:var(--ac-file-muted); font-size:10px; line-height:1.65; text-align:center; overflow-wrap:anywhere; }.ac-file-hint > span { display:block; }
.ac-file-errors { max-height:150px; overflow:auto; margin:14px 0 0; padding:11px 12px 11px 27px; border:1px solid #dbaea1; border-radius:7px; background:#fff5f0; color:#8a3829; font-size:11px; line-height:1.7; overflow-wrap:anywhere; }.ac-file-errors li + li { margin-top:4px; }
.ac-file-list { display:grid; gap:8px; max-height:240px; overflow-y:auto; margin:15px 0 0; padding:3px; list-style:none; }.ac-file-list > li { display:flex; align-items:center; gap:11px; min-width:0; padding:10px 10px 10px 12px; border:1px solid var(--ac-file-line); border-radius:8px; }
.ac-file-type { display:grid; flex-shrink:0; width:35px; height:39px; place-items:center; border:1px solid #d9ddd3; border-radius:4px; background:#f5f4ed; color:#727967; font-size:8px; font-weight:600; letter-spacing:.025em; }
.ac-file-meta { display:flex; flex:1; flex-direction:column; min-width:0; gap:5px; }.ac-file-meta strong { overflow:hidden; font-size:12px; font-weight:500; line-height:1.2; text-overflow:ellipsis; white-space:nowrap; }.ac-file-meta > span { color:var(--ac-file-muted); font-size:10px; }
.ac-file-selected-mark { display:grid; flex-shrink:0; width:17px; height:17px; place-items:center; border-radius:50%; background:#e6eddc; color:var(--ac-file-accent); font-size:10px; }
.ac-file-remove { display:grid; flex-shrink:0; width:34px; height:34px; padding:0; place-items:center; border:0; border-radius:5px; background:transparent; color:var(--ac-file-muted); font:400 23px/1 Arial,Helvetica,sans-serif; cursor:pointer; }.ac-file-remove:hover:enabled { background:#f0eee7; color:var(--ac-file-ink); }
.ac-file-footer { display:flex; justify-content:space-between; gap:16px; margin-top:16px; color:var(--ac-file-muted); font-size:10px; line-height:1.5; font-variant-numeric:tabular-nums; }
.ac-file-dropzone[data-disabled=true] { opacity:.6; }.ac-file-dropzone button:disabled { cursor:not-allowed; }
.ac-file-sr { position:absolute; width:1px; height:1px; overflow:hidden; clip-path:inset(50%); white-space:nowrap; }
@container (width < 350px) { .ac-file-drop-area { padding:21px 12px 17px; }.ac-file-drop-title { font-size:18px; }.ac-file-list > li { gap:8px; padding:8px; }.ac-file-selected-mark { display:none; } }
@media (max-width:420px) { .ac-file-dropzone { padding:18px; } }
@media (prefers-reduced-motion:reduce) { .ac-file-drop-area,.ac-file-browse { transition:none; } }

/* Neutral form surfaces follow the host; green actions and file artwork remain colored. */
:where([data-theme="dark"], .dark) .ac-file-dropzone { --ac-file-paper: #1c201c; --ac-file-ink: #eef1e9; --ac-file-muted: #adb5a7; --ac-file-line: #434b3f; --ac-file-focus: #8cc6f4; }
:where([data-theme="dark"], .dark) .ac-file-drop-area { border-color: #697561; background: #252b23; }
:where([data-theme="dark"], .dark) .ac-file-drop-icon > span { border-color: #252b23; }
:where([data-theme="dark"], .dark) .ac-file-drop-area[data-dragging="true"] { background: #293e2a; border-color: #98b68c; outline-color: #98b68c40; }
:where([data-theme="dark"], .dark) .ac-file-drop-area[data-dragging="true"] .ac-file-drop-icon > span { border-color: #293e2a; }
:where([data-theme="dark"], .dark) .ac-file-drop-icon svg { stroke: #a5b69c; }
:where([data-theme="dark"], .dark) .ac-file-type { border-color: var(--ac-file-line); background: #2b3027; color: #c2cbb7; }
:where([data-theme="dark"], .dark) .ac-file-remove:hover:enabled { background: #343b2f; }
:where([data-theme="dark"], .dark) .ac-file-errors { border-color: #8e5a4d; background: #36251f; color: #efb6a5; }
